begin;
create table public.engineering_production_periods(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,work_id uuid not null,competence date not null check(competence=date_trunc('month',competence)::date),status text not null default 'open' check(status in('open','closed')),closed_at timestamptz,closed_by uuid references auth.users(id),reopened_at timestamptz,reopened_by uuid references auth.users(id),reopen_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,company_id,work_id) references public.works(tenant_id,company_id,id) on delete restrict,unique(tenant_id,company_id,work_id,competence),unique(tenant_id,company_id,id));
create table public.engineering_production_entries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,production_period_id uuid not null,employment_contract_id uuid not null,structure_id uuid not null,service_id uuid not null,production_date date not null,executed_quantity numeric(18,6) not null check(executed_quantity>0),unit_value numeric(18,6),production_value numeric(18,2) generated always as(case when unit_value is null then null else round(executed_quantity*unit_value,2) end) stored,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,company_id,production_period_id) references public.engineering_production_periods(tenant_id,company_id,id) on delete restrict,foreign key(tenant_id,company_id,employment_contract_id) references public.employment_contracts(tenant_id,company_id,id) on delete restrict,foreign key(tenant_id,company_id,service_id) references public.engineering_services(tenant_id,company_id,id) on delete restrict,unique(tenant_id,company_id,id));
create table public.engineering_production_reopen_log(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,production_period_id uuid not null,reason text not null,actor_user_id uuid references auth.users(id),created_at timestamptz not null default now(),foreign key(tenant_id,company_id,production_period_id) references public.engineering_production_periods(tenant_id,company_id,id) on delete restrict);
create index engineering_production_entries_period_idx on public.engineering_production_entries(tenant_id,company_id,production_period_id);create index engineering_production_entries_employee_idx on public.engineering_production_entries(tenant_id,company_id,employment_contract_id,production_date);create index engineering_production_entries_structure_idx on public.engineering_production_entries(tenant_id,company_id,structure_id,service_id);create index engineering_production_reopen_idx on public.engineering_production_reopen_log(tenant_id,company_id,production_period_id,created_at);
create or replace function public.validate_engineering_production_entry() returns trigger language plpgsql set search_path='' as $$declare v_work uuid;v_status text;v_structure_work uuid;v_hired date;v_terminated date;v_emp_status text;begin select work_id,status into v_work,v_status from public.engineering_production_periods where tenant_id=new.tenant_id and company_id=new.company_id and id=new.production_period_id;if not found then raise exception 'production period not found';end if;if v_status<>'open' then raise exception 'closed production period is locked';end if;select work_id into v_structure_work from public.work_structures where tenant_id=new.tenant_id and company_id=new.company_id and id=new.structure_id;if not found or v_structure_work<>v_work then raise exception 'structure does not belong to production work';end if;select hired_on,terminated_on,status into v_hired,v_terminated,v_emp_status from public.employment_contracts where tenant_id=new.tenant_id and company_id=new.company_id and id=new.employment_contract_id;if not found then raise exception 'employee contract not found in company scope';end if;if new.production_date<v_hired or(v_terminated is not null and new.production_date>v_terminated) then raise exception 'production date outside employment contract period';end if;if date_trunc('month',new.production_date)::date<>(select competence from public.engineering_production_periods where id=new.production_period_id) then raise exception 'production date must belong to period competence';end if;return new;end$$;revoke all on function public.validate_engineering_production_entry() from public,anon,authenticated;create trigger engineering_production_entries_validate before insert or update on public.engineering_production_entries for each row execute function public.validate_engineering_production_entry();
create or replace function public.guard_engineering_production_delete() returns trigger language plpgsql set search_path='' as $$declare v_status text;begin select status into v_status from public.engineering_production_periods where id=old.production_period_id;if v_status<>'open' then raise exception 'closed production period is locked';end if;return old;end$$;revoke all on function public.guard_engineering_production_delete() from public,anon,authenticated;create trigger engineering_production_entries_delete_guard before delete on public.engineering_production_entries for each row execute function public.guard_engineering_production_delete();
create or replace function public.set_engineering_production_period_status(p_period_id uuid,p_action text,p_reason text default null) returns void language plpgsql security invoker set search_path='' as $$declare v public.engineering_production_periods%rowtype;begin select * into v from public.engineering_production_periods where id=p_period_id for update;if not found or not app_private.can_access_company(v.tenant_id,v.company_id) then raise exception 'production period not found or inaccessible';end if;if p_action='close' then if v.status<>'open' then raise exception 'only open period can be closed';end if;update public.engineering_production_periods set status='closed',closed_at=now(),closed_by=(select auth.uid()) where id=v.id;elsif p_action='reopen' then if v.status<>'closed' then raise exception 'only closed period can be reopened';end if;if nullif(trim(p_reason),'') is null then raise exception 'reopen reason is required';end if;update public.engineering_production_periods set status='open',reopened_at=now(),reopened_by=(select auth.uid()),reopen_reason=p_reason where id=v.id;insert into public.engineering_production_reopen_log(tenant_id,company_id,production_period_id,reason,actor_user_id) values(v.tenant_id,v.company_id,v.id,p_reason,(select auth.uid()));else raise exception 'invalid production action';end if;end$$;revoke all on function public.set_engineering_production_period_status(uuid,text,text) from public,anon;grant execute on function public.set_engineering_production_period_status(uuid,text,text) to authenticated;
create view public.engineering_employee_production_summary with(security_invoker=true) as select p.tenant_id,p.company_id,p.work_id,p.competence,e.employment_contract_id,ec.employee_id,sum(e.executed_quantity)::numeric(18,6) executed_quantity,coalesce(sum(e.production_value),0)::numeric(18,2) production_value from public.engineering_production_periods p join public.engineering_production_entries e on e.tenant_id=p.tenant_id and e.company_id=p.company_id and e.production_period_id=p.id join public.employment_contracts ec on ec.tenant_id=e.tenant_id and ec.company_id=e.company_id and ec.id=e.employment_contract_id group by p.tenant_id,p.company_id,p.work_id,p.competence,e.employment_contract_id,ec.employee_id;
create trigger engineering_production_periods_updated before update on public.engineering_production_periods for each row execute function public.set_updated_at();create trigger engineering_production_entries_updated before update on public.engineering_production_entries for each row execute function public.set_updated_at();alter table public.engineering_production_periods enable row level security;alter table public.engineering_production_entries enable row level security;alter table public.engineering_production_reopen_log enable row level security;create policy engineering_production_periods_select on public.engineering_production_periods for select to authenticated using(app_private.can_access_company(tenant_id,company_id));create policy engineering_production_periods_write on public.engineering_production_periods for all to authenticated using(app_private.can_access_company(tenant_id,company_id)) with check(app_private.can_access_company(tenant_id,company_id));create policy engineering_production_entries_select on public.engineering_production_entries for select to authenticated using(app_private.can_access_company(tenant_id,company_id));create policy engineering_production_entries_write on public.engineering_production_entries for all to authenticated using(app_private.can_access_company(tenant_id,company_id)) with check(app_private.can_access_company(tenant_id,company_id));create policy engineering_production_reopen_select on public.engineering_production_reopen_log for select to authenticated using(app_private.can_access_company(tenant_id,company_id));commit;